package edu.klh.soa.recall; import jakarta.persistence.*;import java.time.Instant; @Entity @Table(name="recall_record") public class RecallRecord {@Id public String eventId; @Column(nullable=false) public String lotCode;@Column(nullable=false) public String productCode;@Column(nullable=false) public String reason;@Column(nullable=false) public String status;@Column(nullable=false) public Instant occurredAt;protected RecallRecord(){}public RecallRecord(String id,String lot,String product,String reason,Instant at){eventId=id;lotCode=lot;productCode=product;this.reason=reason;occurredAt=at;status="PUBLISHED";}}